// Runs whenever a LendLoop workflow fails (after its own retries). Logs the failure and
// reports it to Convex so it appears in the app's admin 'Automation health' panel.
// Only the workflow name, execution id and error message leave n8n: no payload data.
const crypto = require('crypto');
const e = $input.first().json;
const report = {
  executionId: String(e.execution?.id ?? `manual-${Date.now()}`),
  workflow: e.workflow?.name ?? 'unknown',
  message: String(e.execution?.error?.message ?? 'unknown error').slice(0, 300),
};
console.error(`[LendLoop error] ${report.workflow} execution ${report.executionId}: ${report.message}`);
const body = JSON.stringify(report);
const ts = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, signature } }];
